"use strict";(function(){var price=new Price.AzurePackPrice;var azurepackCalculator=new AzurePack.Calculator(price);var addButton=document.getElementsByClassName("azurepack_addButton")[0];var clearItemsButton=document.getElementsByClassName("azurepack_clearItemsButton")[0];var clearListButton=document.getElementsByClassName("azurepack_clearListButton")[0];var clearLastButton=document.getElementsByClassName("azurepack_clearLastButton")[0];var resultSpace=document.getElementsByClassName("resultSpace")[0];var downloadSpace=document.getElementsByClassName("downloadSpace")[0];Modules.Events.addListener(addButton,"click",addToList);Modules.Events.addListener(clearItemsButton,"click",clearItems);Modules.Events.addListener(clearListButton,"click",clearList);Modules.Events.addListener(clearLastButton,"click",clearLast);var serverName=document.getElementsByClassName("azurepack_serverName")[0];var cores=document.getElementsByClassName("azurepack_cores")[0];var disk=document.getElementsByClassName("azurepack_disk")[0];var snapshots=document.getElementsByClassName("azurepack_snapshotCount")[0];var ram=document.getElementsByClassName("azurepack_ram")[0];var ipv4=document.getElementsByClassName("azurepack_ipv4")[0];var vLANs=document.getElementsByClassName("azurepack_vLANs")[0];var VPNs=document.getElementsByClassName("azurepack_VPNs")[0];var discounts=document.getElementsByClassName("azurepack_discounts")[0];var azurepackServersTable=document.getElementsByClassName("azurepackServersTable")[0].getElementsByTagName("tbody")[0];var azurepackInfrastructureTable=document.getElementsByClassName("azurepackInfrastructureTable")[0].getElementsByTagName("tbody")[0];var sum=0;var costOfServersList=[];var exportDoc="";var exportResult="";serverName.focus();var minCPUCores=1;var maxCPUCores=48;var minDiskCapacity=25;var maxDiskCapacity=65536;var minRamCapacity=2;var maxRamCapacity=256;var minipv4=0;var maxipv4=10;var vLANsDefault=2;var minvLANs=2;var VPNsDefault=2;var minVPNs=2;function addToList(){var regionValue=1;console.log("azurepack_region:"+regionValue);var serverNameValue=validateServerName(serverName.value);console.log("azurepack_validated_serverName:"+serverNameValue);var coresValue=validateCPULimits(isNumberInputCorrect(cores.value));console.log("azurepack_validated_coresValue:"+coresValue);var ramValue=validateRamLimits(isNumberInputCorrect(ram.value));console.log("azurepack_validated_RamCapacity:"+ramValue);var diskValue=validateDiskLimits(isNumberInputCorrect(disk.value));console.log("azurepack_validated_diskCapacity:"+diskValue);var snapshotsValue=validateSnapshotsLimits(isNumberInputCorrect(snapshots.value));console.log("azurepack_validated_snapshotsCapacity:"+snapshotsValue);var ipv4Value=validateipv4Limits(isNumberInputCorrect(ipv4.value));console.log("azurepack_validated_ipv4Limits:"+ipv4Value);var vLANsValue=validatevLANsLimits(isNumberInputCorrect(vLANs.value));console.log("azurepack_validated_vLANsLimits:"+vLANsValue);var VPNsValue=validateVPNsLimits(isNumberInputCorrect(VPNs.value));console.log("azurepack_validated_vLANsLimits:"+VPNsValue);var discountValue=discounts.selectedIndex;console.log("region:"+discounts.value);var azurepackServer=new AzurePack.Server(regionValue,serverNameValue,coresValue,ramValue,diskValue,snapshotsValue,ipv4Value);azurepackCalculator.addServer(azurepackServer);var costOfInfrastructure=azurepackCalculator.getCostOfInfrastructure();virtuozzoCalculator.addServer(virtuozzoServer);var costOfServer=virtuozzoCalculator.getCostOfServer(virtuozzoServer);costOfServersList.push(parseFloat(costOfServer));sum+=parseFloat(costOfServer);Modules.Events.Messages.send("updateVirtuozzoServersList","");var row=azurepackServersTable.insertRow(azurepackServersTable.rows.length);var cellServerName=row.insertCell(0);cellServerName.appendChild(document.createTextNode(serverNameValue));var cellRegion=row.insertCell(1);if(regionValue==0){cellRegion.appendChild(document.createTextNode("Россия, Санкт-Петербург (SSD)"))}else if(regionValue==1){cellRegion.appendChild(document.createTextNode("Россия, Москва (Tier III Gold, SSD-cache)"))}else if(regionValue==2){cellRegion.appendChild(document.createTextNode("Европа, Амстердам (SSD)"))}var cellCores=row.insertCell(2);cellCores.appendChild(document.createTextNode(coresValue));var cellFrequency=row.insertCell(3);cellFrequency.appendChild(document.createTextNode(frequencyValue+" ГГц."));var cellRam=row.insertCell(4);cellRam.appendChild(document.createTextNode(ramValue+" ГБ."));var cellDisk=row.insertCell(5);cellDisk.appendChild(document.createTextNode(diskValue+" ГБ."));var cellBackups=row.insertCell(6);cellBackups.appendChild(document.createTextNode(backupCountValue*backupSpaceValue+" ГБ."));var cellIPv4=row.insertCell(7);cellIPv4.appendChild(document.createTextNode(ipv4Value));var cellTrafficOut=row.insertCell(8);cellTrafficOut.appendChild(document.createTextNode(trafficOutValue+" ГБ."));var cellVtType=row.insertCell(9);if(vtTypeIndex==1){cellVtType.appendChild(document.createTextNode("Виртуальная машина"))}else{cellVtType.appendChild(document.createTextNode(vtType.value))}var cellOSType=row.insertCell(10);cellOSType.appendChild(document.createTextNode(osType.value));var cellRunning=row.insertCell(11);if(parseFloat(runningDaysValue)!=0&&parseFloat(runningHoursValue)!=0){cellRunning.appendChild(document.createTextNode(runningDaysValue+" дн., "+runningHoursValue+"ч."))}else if(parseFloat(runningDaysValue)==0&&parseFloat(runningHoursValue)!=0){cellRunning.appendChild(document.createTextNode(runningHoursValue+" ч."))}else if(parseFloat(runningDaysValue)!=0&&parseFloat(runningHoursValue)==0){cellRunning.appendChild(document.createTextNode(runningDaysValue+" дн."))}else if(parseFloat(runningDaysValue)==0&&parseFloat(runningHoursValue)==0){cellRunning.appendChild(document.createTextNode("-"))}var cellStopped=row.insertCell(12);if(parseFloat(stoppedDaysValue)!=0&&parseFloat(stoppedHoursValue)!=0){cellStopped.appendChild(document.createTextNode(stoppedDaysValue+" дн., "+stoppedHoursValue+"ч."))}else if(parseFloat(stoppedDaysValue)==0&&parseFloat(stoppedHoursValue)!=0){cellStopped.appendChild(document.createTextNode(stoppedHoursValue+" ч."))}else if(parseFloat(stoppedDaysValue)!=0&&parseFloat(stoppedHoursValue)==0){cellStopped.appendChild(document.createTextNode(stoppedDaysValue+" дн."))}else if(parseFloat(stoppedDaysValue)==0&&parseFloat(stoppedHoursValue)==0){cellStopped.appendChild(document.createTextNode("-"))}var cellServerCost=row.insertCell(13);cellServerCost.appendChild(document.createTextNode(costOfServer+" руб."));updateResult();serverName.focus()}function clearItems(){serverName.value="";cores.value="";frequency.value="";disk.value="";snapshotCount.value="";backupSpace.value="";ram.value="";ipv4.value="";trafficOut.value="";runningDays.value="";runningHours.value="";stoppedDays.value="";stoppedHours.value=""}function clearList(){while(azurepackServersTable.rows[0])azurepackServersTable.deleteRow(0);sum=0;costOfServersList=[];updateResult()}function clearLast(){azurepackServersTable.deleteRow(azurepackServersTable.rows.length-1);sum=sum-costOfServersList[costOfServersList.length-1];costOfServersList.pop();updateResult()}function updateResult(){resultSpace.innerHTML="<h3 class='resultHeader'>"+"Примерная стоимость облачной инфраструктуры: "+parseFloat(sum).toFixed(2).toString()+" руб."+"</h3>";exportResult="Примерная стоимость облачной инфраструктуры: "+parseFloat(sum).toFixed(2).toString()+" руб. в месяц"+"\r\n"}function generateExportLink(content){downloadSpace.innerHTML="";var exportLink=downloadSpace.appendChild(document.createElement("a"));exportLink.download="export.txt";exportLink.innerHTML="Примерный счет (txt)";console.log(content.toString());exportLink.href="data:text/plain;charset=utf-8,"+content}function isNumberInputCorrect(text){text=checkCommaInInput(text);return text}function checkCommaInInput(text){text=text.replace(/,/g,".");return text}function validateServerName(serverNameValue){if(isEmptyOrSpaces(serverNameValue)==true){serverName.value="Облачный сервер";return"Облачный сервер"}else{return serverNameValue}}function isEmptyOrSpaces(str){return str===null||str.match(/^ *$/)!==null}function validateCPULimits(coresValue){if(isEmptyOrSpaces(coresValue)){cores.value=minCPUCores;return minCPUCores}if(coresValue<minCPUCores){cores.value=minCPUCores;return minCPUCores}else if(coresValue>maxCPUCores){cores.value=maxCPUCores;return maxCPUCores}return coresValue}function validateDiskLimits(diskCapacity){if(isEmptyOrSpaces(diskCapacity)){disk.value=minDiskCapacity;return minDiskCapacity}if(diskCapacity<minDiskCapacity){disk.value=minDiskCapacity;return minDiskCapacity}else if(diskCapacity>maxDiskCapacity){disk.value=maxDiskCapacity;return maxDiskCapacity}return diskCapacity}function validateSnapshotsLimits(snapshotsCapacity){if(isEmptyOrSpaces(snapshotsCapacity)){snapshotsCapacity=0;return snapshotsCapacity}if(snapshotsCapacity<0){snapshotsCapacity=0;return snapshotsCapacity}return snapshotsCapacity}function validatebackupCount(backupCountValue){if(isEmptyOrSpaces(backupCountValue)){snapshotCount.value=0;return 0}if(backupCountValue<0){snapshotCount.value=0;return 0}else return backupCountValue}function validatebackupSpace(backupSpaceValue,diskCapacity,backupCountValue){if(isEmptyOrSpaces(backupSpaceValue)||backupCountValue==0){backupSpace.value=0;return 0}if(backupSpaceValue<0){backupSpace.value=0;return 0}else if(backupSpaceValue>diskCapacity){backupSpace.value=diskCapacity;return diskCapacity}else return backupSpaceValue}function validateRamLimits(ramCapacity){if(isEmptyOrSpaces(ramCapacity)){ram.value=minRamCapacity;return minRamCapacity}if(ramCapacity<minRamCapacity){ram.value=minRamCapacity;return minRamCapacity}else if(ramCapacity>maxRamCapacity){ram.value=maxRamCapacity;return maxRamCapacity}return ramCapacity}function validateipv4Limits(ipv4Count){if(isEmptyOrSpaces(ipv4Count)){ipv4.value=1;return 1}if(ipv4Count<minipv4){ipv4.value=minipv4;return minipv4}else if(ipv4Count>maxipv4){ipv4.value=maxipv4;return maxipv4}return ipv4Count}function validatevLANsLimits(vLANsCount){if(isEmptyOrSpaces(vLANsCount)){vLANs.value=vLANsDefault;return vLANsDefault}if(vLANsCount<minvLANs){vLANs.value=minvLANs;return minvLANs}else return vLANsCount}function validateVPNsLimits(VPNsCount){if(isEmptyOrSpaces(VPNsCount)){VPNs.value=VPNsDefault;return VPNsDefault}if(VPNsCount<minVPNs){VPNs.value=minVPNs;return minVPNs}else return VPNsCount}})();